const PAGE_SLOTS:usize=128;const FRAME_PAGE_SLOTS:usize=8;
#[derive(Clone,Copy,Debug,PartialEq,Eq,semio_framework_value::RetireOwned)]
pub struct PreparationIdentity{pub standard:u8,pub instance:u32,pub operation:u64,pub generation:u64,pub revision:[u8;32],pub source:[u8;1024],pub source_len:u16}
impl PreparationIdentity{pub fn valid(&self)->bool{matches!(self.standard,2|4)&&self.instance!=0&&self.operation!=0&&self.source_len>0&&(self.source_len as usize)<=self.source.len()&&std::str::from_utf8(&self.source[..self.source_len as usize]).is_ok_and(|value|value.chars().count()<=256)}}
#[derive(Clone,Copy,Debug,semio_framework_value::RetireOwned)]
pub struct PreparationLimits{pub work:usize,pub source_bytes:usize,pub scratch_bytes:usize,pub result_bytes:usize,pub vertices:usize,pub triangles:usize,pub depth:usize}
#[derive(Clone,Copy,Debug,semio_framework_value::RetireOwned)]
pub enum PreparationScope{Product(u64),Model}
#[derive(Clone,Copy,Debug,semio_framework_value::RetireOwned)]
pub struct PreparationRequest{pub identity:PreparationIdentity,pub scope:PreparationScope,pub limits:PreparationLimits}
#[derive(Clone,Copy,Debug,PartialEq,Eq,semio_framework_value::RetireOwned)]
pub enum PreparationPhase{Admitting,Indexing,Relationships,Selecting,Publishing,Retiring,Projecting,Ready,Cancelling,Closing,Closed,Refused}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct PreparationProgress{pub phase:PreparationPhase,pub work:usize,pub source_bytes:usize,pub scratch_bytes:usize,pub result_bytes:usize,pub published:bool,pub indexed_entities:usize,pub products_completed:usize,pub products_skipped:usize,pub reason:Option<&'static str>}
/// 🔒️ The embedding original typed owner retains its immutable SnapshotRead through all turns and close.
pub struct CapturedGeometryRead<'a,G:GeometryGraph>{pub identity:&'a PreparationIdentity,pub source_bytes:usize,pub graph:&'a G}
/// 🎟️ No fresh context is created; every unit and physical receipt debit the supplied initiating caller.
pub struct PreparationTurn<'a,'cx>{pub identity:&'a PreparationIdentity,pub cx:&'a mut StepContext<'cx>}
pub struct PreparedPrimitive<'a>{pub product:u64,pub representation:u64,pub label:&'a str,vertices:&'a mesh::RetainedMeshPages<f64>,triangles:&'a mesh::RetainedMeshPages<u32>,vertex_start:usize,vertex_count:usize,triangle_start:usize,triangle_count:usize}
impl PreparedPrimitive<'_>{pub fn vertex_count(&self)->usize{self.vertex_count}pub fn triangle_count(&self)->usize{self.triangle_count}pub fn position(&self,vertex:usize,axis:usize)->Result<f64,&'static str>{if vertex>=self.vertex_count{return Err("preparation-output-index")}self.vertices.get(self.vertex_start+vertex,axis)}pub fn index(&self,triangle:usize,corner:usize)->Result<u32,&'static str>{if triangle>=self.triangle_count{return Err("preparation-output-index")}self.triangles.get(self.triangle_start+triangle,corner)}}
#[derive(Clone,Copy,Default,semio_framework_value::RetireOwned)]
struct Slot{id:u64,ordinal:u64}
#[derive(Clone,Copy,semio_framework_value::RetireOwned)]
struct Frame{kind:u64,id:u64,stage:u64,a:u64,b:u64,c:u64,ordinal:u64,pad:u64,matrix:[[f64;4];4],base:[[f64;3];4],vector:[f64;3],dims:[f64;3],tail:[u64;22]}
impl Frame{fn new(kind:u64,id:u64)->Self{Self{kind,id,stage:0,a:0,b:0,c:0,ordinal:0,pad:0,matrix:Mat4::identity().0,base:[[0.;3];4],vector:[0.;3],dims:[0.;3],tail:[0;22]}}fn child(kind:u64,id:u64,a:u64)->Self{let mut value=Self::new(kind,id);value.a=a;value}}
fn hash(mut id:u64)->u64{id=(id^(id>>30)).wrapping_mul(0xbf58476d1ce4e5b9);id=(id^(id>>27)).wrapping_mul(0x94d049bb133111eb);id^(id>>31)}
type IndexPage=[Slot;PAGE_SLOTS];type FramePage=[Frame;FRAME_PAGE_SLOTS];
/// 🧭️ Explicit paid source/index/placement/primitive frontiers without a one-shot projector fallback.
#[derive(semio_framework_value::RetireOwned)]
pub struct GeometryPreparationCursor{request:PreparationRequest,phase:PreparationPhase,reason:Option<&'static str>,work:usize,source_bytes:usize,scratch_bytes:usize,result_bytes:usize,source_identity:Option<usize>,source_length:Option<usize>,pages:Option<Vec<Box<IndexPage>>>,frames:Option<Vec<Box<FramePage>>>,slots:usize,page_count:usize,source:usize,probe:Option<usize>,depth:usize,points:Option<mesh::RetainedMeshPages<f64>>,triangles:Option<mesh::RetainedMeshPages<u32>>,emitted:usize,emission_pending:bool,primitive:u64,representation:u64,product_ordinal:usize,allocation:u8,target:u64,relationship:usize,relationship_host:u64,selection:usize,record_phase:u8,record_count:usize,issue_count:usize,vertex_start:usize,triangle_start:usize,representation_ordinal:usize,records:Option<mesh::RetainedMeshPages<u32>>,issues:Option<mesh::RetainedMeshPages<u32>>,issue_kind:u32,vertices:Option<vertex::SourceVertexIndex>,vertex_generation:u32}
impl GeometryPreparationCursor{
 pub fn new(request:PreparationRequest)->Result<Self,&'static str>{let limits=request.limits;if !request.identity.valid()||matches!(request.scope,PreparationScope::Product(0))||limits.vertices>u32::MAX as usize||limits.triangles>u32::MAX as usize||[limits.work,limits.source_bytes,limits.scratch_bytes,limits.result_bytes,limits.vertices,limits.triangles,limits.depth].contains(&0){return Err("invalid-preparation-request")}Ok(Self{request,phase:PreparationPhase::Admitting,reason:None,work:0,source_bytes:0,scratch_bytes:0,result_bytes:0,source_identity:None,source_length:None,pages:None,frames:None,slots:0,page_count:0,source:0,probe:None,depth:0,points:None,triangles:None,emitted:0,emission_pending:false,primitive:0,representation:0,product_ordinal:0,allocation:0,target:match request.scope{PreparationScope::Product(id)=>id,PreparationScope::Model=>0},relationship:0,relationship_host:0,selection:0,record_phase:0,record_count:0,issue_count:0,vertex_start:0,triangle_start:0,representation_ordinal:0,records:None,issues:None,issue_kind:0,vertices:None,vertex_generation:0})}
 pub fn progress(&self)->PreparationProgress{PreparationProgress{phase:self.phase,work:self.work,source_bytes:self.source_bytes,scratch_bytes:self.scratch_bytes,result_bytes:self.result_bytes,published:self.phase==PreparationPhase::Ready,indexed_entities:self.source,products_completed:if matches!(self.request.scope,PreparationScope::Model){self.record_count}else{usize::from(self.phase==PreparationPhase::Ready)},products_skipped:self.issue_count,reason:self.reason}}
 fn admit(&mut self,turn:&mut PreparationTurn<'_,'_>,copy:usize,capacity:usize,release:usize,depth:usize)->Result<bool,&'static str>{turn.cx.original_source_parent().map_err(|_|"preparation-requires-original-source-authority")?;if *turn.identity!=self.request.identity||turn.cx.operation().0!=self.request.identity.operation||turn.cx.generation().0!=self.request.identity.generation{return Err("preparation-original-caller-changed")}if turn.cx.is_cancelled()&&self.phase!=PreparationPhase::Closing{self.phase=PreparationPhase::Cancelling;return Ok(false)}let demand=RetirementDemand{copy_bytes:copy,capacity_bytes:capacity,release_bytes:release,depth};if turn.cx.fuel_remaining()==0||(if self.phase==PreparationPhase::Closing{turn.cx.retirement_should_yield()}else{turn.cx.should_yield()})||!turn.cx.retained_work_can_enter(demand){return Ok(false)}if self.phase!=PreparationPhase::Closing&&self.work>=self.request.limits.work{self.refuse("preparation-work-limit");return Ok(false)}turn.cx.consume_fuel(1);turn.cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:capacity,released_bytes:release}).map_err(|_|"preparation-original-receipt-refused")?;self.work=self.work.saturating_add(1);Ok(true)}
 fn refuse(&mut self,reason:&'static str){self.phase=PreparationPhase::Refused;self.reason=Some(reason);}
 fn read_frame(&self,slot:usize)->Frame{self.frames.as_ref().unwrap()[slot/FRAME_PAGE_SLOTS][slot%FRAME_PAGE_SLOTS]}
 fn write_frame(&mut self,slot:usize,value:Frame){self.frames.as_mut().unwrap()[slot/FRAME_PAGE_SLOTS][slot%FRAME_PAGE_SLOTS]=value;}
 fn push(&mut self,value:Frame)->Result<(),&'static str>{if self.depth>=self.request.limits.depth{return Err("preparation-depth-limit")}self.write_frame(self.depth,value);self.depth+=1;Ok(())}
 fn finish(&mut self,value:Frame){self.write_frame(self.request.limits.depth,value);self.depth-=1;}
 fn call(&mut self,mut current:Frame,next:Frame,stage:u64)->Result<(),&'static str>{current.stage=stage;self.write_frame(self.depth-1,current);self.push(next)}
 fn entry(&self,slot:usize)->Slot{self.pages.as_ref().unwrap()[slot/PAGE_SLOTS][slot%PAGE_SLOTS]}
 fn store(&mut self,slot:usize,id:u64,ordinal:usize){self.pages.as_mut().unwrap()[slot/PAGE_SLOTS][slot%PAGE_SLOTS]=Slot{id,ordinal:ordinal as u64+1};}
 fn reference<V:GeometryValue>(entity:GeometryEntity<'_,V>,index:usize,optional:bool)->Result<u64,&'static str>{match entity.args.get(index){None if optional=>Ok(0),Some(value)if optional&&value.is_unset()=>Ok(0),Some(value)=>value.as_reference().ok_or("preparation-missing-reference"),_=>Err("preparation-missing-reference")}}
 fn number<V:GeometryValue>(value:Option<&V>)->Result<f64,&'static str>{value.and_then(GeometryValue::as_real).filter(|v|v.is_finite()).ok_or("preparation-missing-finite-number")}
 fn run<G:GeometryGraph>(&mut self,read:&CapturedGeometryRead<'_,G>,mut current:Frame)->Result<(),&'static str>{
  let returned=self.read_frame(self.request.limits.depth);let entity=if current.id==0{None}else{Some(read.graph.entity((current.ordinal-1)as usize).ok_or("preparation-source-entity-changed")?)};if entity.is_some_and(|e|e.id!=current.id||e.constituent_count!=1){return Err("preparation-complex-or-changed-entity")}let reference=|index,optional|Self::reference(entity.ok_or("preparation-missing-entity")?,index,optional);let mut result=Frame::new(0,0);
  match current.kind{
   1=>match current.stage{0=>{let name=entity.unwrap().name;if !super::product::is_geometry_product(read.graph.standard(),name)||matches!(name,"IFCOPENINGELEMENT"|"IFCOPENINGSTANDARDCASE"){return Err("preparation-target-must-be-renderable-product")}self.product_ordinal=(current.ordinal-1)as usize;current.a=reference(5,true)?;self.call(current,Frame::new(2,reference(6,false)?),1)?},1=>{current.b=returned.b;current.c=returned.a;self.representation_ordinal=(returned.ordinal-1)as usize;current.dims[2]=returned.kind as f64;self.call(current,Frame::new(3,returned.c),2)?},2=>{current.matrix=returned.matrix;self.call(current,Frame::new(4,current.a),3)?},3=>{let mut next=Frame::child(8,current.b,current.dims[2]as u64);next.matrix=Mat4(current.matrix).mul(&Mat4(returned.matrix)).0;self.call(current,next,4)?},_=>{self.representation=current.c;self.primitive=returned.kind;if returned.kind==3{self.emitted=20;}self.finish(returned)}},
   2=>{if current.stage==0{let entity=entity.unwrap();if !matches!(entity.name,"IFCPRODUCTDEFINITIONSHAPE"|"IFCPRODUCTREPRESENTATION"){return Err("preparation-invalid-product-shape")}let list=entity.args.get(2).and_then(GeometryValue::as_aggregate).filter(|v|v.len()==1).ok_or("preparation-single-representation-required")?;self.call(current,Frame::new(10,list[0].as_reference().ok_or("preparation-invalid-representation")?),1)?}else{self.finish(returned)}},
   10=>{let entity=entity.unwrap();if entity.name!="IFCSHAPEREPRESENTATION"{return Err("preparation-invalid-shape-representation")}if entity.args.get(1).and_then(GeometryValue::as_str)!=Some("Body")||!entity.args.get(2).and_then(GeometryValue::as_str).is_some_and(|name|matches!(name,"CSG"|"SweptSolid"|"Tessellation")){return Err("preparation-unsupported-representation")}let items=entity.args.get(3).and_then(GeometryValue::as_aggregate).filter(|v|v.len()==1).ok_or("preparation-single-item-required")?;result.kind=if entity.args.get(2).and_then(GeometryValue::as_str)==Some("CSG"){1}else if entity.args.get(2).and_then(GeometryValue::as_str)==Some("SweptSolid"){2}else{3};result.ordinal=current.ordinal;result.a=current.id;result.b=items[0].as_reference().ok_or("preparation-invalid-item")?;result.c=reference(0,false)?;self.finish(result)},
   3=>{if current.stage==1{self.finish(returned)}else{let entity=entity.unwrap();match entity.name{"IFCGEOMETRICREPRESENTATIONCONTEXT"=>{if Self::number(entity.args.get(2))?!=3.{return Err("preparation-context-must-be-3d")}self.call(current,Frame::new(5,reference(4,false)?),1)?},"IFCGEOMETRICREPRESENTATIONSUBCONTEXT"=>self.call(current,Frame::new(3,reference(6,false)?),1)?,_=>return Err("preparation-invalid-context")}}},
   4=>{if current.id==0{self.finish(result)}else{match current.stage{0=>{if entity.unwrap().name!="IFCLOCALPLACEMENT"{return Err("preparation-unsupported-placement")}current.a=reference(1,false)?;self.call(current,Frame::new(4,reference(0,true)?),1)?},1=>{current.matrix=returned.matrix;self.call(current,Frame::new(5,current.a),2)?},_=>{result.matrix=Mat4(current.matrix).mul(&Mat4(returned.matrix)).0;self.finish(result)}}}},
   5|6=>{if current.id==0{self.finish(result)}else{match current.stage{0=>{if entity.unwrap().name!=if current.kind==5{"IFCAXIS2PLACEMENT3D"}else{"IFCAXIS2PLACEMENT2D"}{return Err("preparation-invalid-axis")}current.a=reference(1,true)?;current.b=if current.kind==5{reference(2,true)?}else{0};self.call(current,Frame::child(7,reference(0,false)?,if current.kind==5{0}else{4}),1)?},1=>{current.vector=returned.vector;self.call(current,Frame::child(7,current.a,if current.kind==5{2}else{5}),2)?},2 if current.kind==5=>{current.base[0]=normalize_direction(returned.vector).ok_or("preparation-invalid-direction")?;self.call(current,Frame::child(7,current.b,3),3)?},_=>{result.matrix=if current.kind==5{let z=current.base[0];let x=normalize_direction(subtract(returned.vector,scale(z,dot(returned.vector,z)))).ok_or("preparation-invalid-direction")?;matrix(current.vector,x,cross(z,x),z).0}else{let x=normalize_direction(returned.vector).ok_or("preparation-invalid-direction")?;matrix(current.vector,x,[-x[1],x[0],0.],[0.,0.,1.]).0};self.finish(result)}}}},
   7=>{if current.id==0{result.vector=if current.a==2{[0.,0.,1.]}else{[1.,0.,0.]};self.finish(result)}else{let entity=entity.unwrap();let direction=current.a!=0&&current.a!=4;let dimension=if current.a>=4{2}else{3};let items=entity.args.first().and_then(GeometryValue::as_aggregate).filter(|v|v.len()==dimension).ok_or("preparation-coordinate-dimension")?;if entity.name!=if direction{"IFCDIRECTION"}else{"IFCCARTESIANPOINT"}{return Err("preparation-coordinate-dimension")}result.vector=[Self::number(items.first())?,Self::number(items.get(1))?,if dimension==3{Self::number(items.get(2))?}else{0.}];self.finish(result)}},
   8=>{let entity=entity.unwrap();match entity.name{"IFCTRIANGULATEDFACESET"=>{if current.stage==0{if current.a!=3{return Err("preparation-representation-item-type-mismatch")}let mut next=Frame::new(11,current.id);next.matrix=current.matrix;self.call(current,next,100)?}else{self.finish(returned)}},"IFCBLOCK"=>{if current.stage==0{if current.a!=1{return Err("preparation-representation-item-type-mismatch")}if entity.args.len()!=4{return Err("preparation-block-arity")}current.dims=[Self::number(entity.args.get(1))?,Self::number(entity.args.get(2))?,Self::number(entity.args.get(3))?];if current.dims.iter().any(|v|*v<=0.){return Err("preparation-invalid-block-dimensions")}self.call(current,Frame::new(5,reference(0,false)?),1)?}else{result.kind=1;result.matrix=Mat4(current.matrix).mul(&Mat4(returned.matrix)).0;result.dims=current.dims;self.finish(result)}},"IFCEXTRUDEDAREASOLID"=>match current.stage{0=>{if current.a!=2{return Err("preparation-representation-item-type-mismatch")}if entity.args.len()!=4{return Err("preparation-extrusion-arity")}current.a=reference(1,true)?;current.b=reference(2,false)?;current.dims[0]=Self::number(entity.args.get(3))?;if current.dims[0]<=0.{return Err("preparation-invalid-extrusion-depth")}self.call(current,Frame::new(9,reference(0,false)?),10)?},10=>{current.base=returned.base;self.call(current,Frame::new(5,current.a),11)?},11=>{current.matrix=Mat4(current.matrix).mul(&Mat4(returned.matrix)).0;self.call(current,Frame::child(7,current.b,1),12)?},_=>{let direction=normalize_direction(returned.vector).ok_or("preparation-invalid-direction")?;if direction[2].abs()<1e-12{return Err("preparation-extrusion-in-profile-plane")}result.kind=2;result.matrix=current.matrix;result.base=current.base;result.vector=scale(direction,current.dims[0]);self.finish(result)}},_=>return Err("preparation-unsupported-item")}},
   9=>{let entity=entity.unwrap();if current.stage==0{if entity.name!="IFCRECTANGLEPROFILEDEF"||entity.args.len()!=5||entity.args.first().and_then(GeometryValue::as_enum)!=Some("AREA"){return Err("preparation-unsupported-profile")}current.dims=[Self::number(entity.args.get(3))?,Self::number(entity.args.get(4))?,0.];if current.dims[0]<=0.||current.dims[1]<=0.{return Err("preparation-invalid-rectangle-dimensions")}self.call(current,Frame::new(6,reference(2,true)?),1)?}else{for index in 0..4{result.base[index]=Mat4(returned.matrix).transform_point(rectangle_point(current.dims[0],current.dims[1],index));}self.finish(result)}},
   11|12=>self.run_tessellation(read,current,entity.unwrap())?,
   _=>return Err("preparation-invalid-frame")
  }Ok(())
 }

 fn check_source<G:GeometryGraph>(&self,read:&CapturedGeometryRead<'_,G>)->Result<(),&'static str>{let standard=match read.graph.standard(){GeometryStandard::Ifc2x3=>2,GeometryStandard::Ifc4=>4};if *read.identity!=self.request.identity||standard!=self.request.identity.standard||self.source_identity.is_some_and(|identity|identity!=read.graph.source_identity())||self.source_length.is_some_and(|length|length!=read.graph.len())||self.source_identity.is_some()&&read.source_bytes!=self.source_bytes{return Err("preparation-captured-source-changed")}Ok(())}
 pub fn advance<G:GeometryGraph>(&mut self,read:&CapturedGeometryRead<'_,G>,turn:&mut PreparationTurn<'_,'_>)->Result<PreparationProgress,&'static str>{self.check_source(read)?;turn.cx.original_source_parent().map_err(|_|"preparation-requires-original-source-authority")?;if *turn.identity!=self.request.identity||turn.cx.operation().0!=self.request.identity.operation||turn.cx.generation().0!=self.request.identity.generation{return Err("preparation-original-caller-changed")}if turn.cx.is_cancelled()&&!matches!(self.phase,PreparationPhase::Closing|PreparationPhase::Closed){self.phase=PreparationPhase::Cancelling;}if matches!(self.phase,PreparationPhase::Ready|PreparationPhase::Refused|PreparationPhase::Closing|PreparationPhase::Closed|PreparationPhase::Cancelling){return Ok(self.progress())}if let Err(reason)=self.advance_unit(read,turn){if matches!(self.request.scope,PreparationScope::Model)&&self.phase==PreparationPhase::Projecting&&!reason.contains("work-limit")&&!reason.contains("byte-limit")&&!reason.contains("result-limit")&&!reason.contains("generation-limit"){self.reason=Some(reason);self.issue_kind=if reason.contains("unsupported"){2}else if reason.contains("opening"){3}else{1};self.depth=0;self.emission_pending=false;self.phase=PreparationPhase::Retiring}else{self.refuse(reason)}}if self.phase==PreparationPhase::Ready{if turn.cx.is_cancelled(){self.phase=PreparationPhase::Cancelling}else if turn.cx.deadline_exceeded(){self.phase=if matches!(self.request.scope,PreparationScope::Model){PreparationPhase::Selecting}else{PreparationPhase::Projecting}}}Ok(self.progress())}
 fn advance_unit<G:GeometryGraph>(&mut self,read:&CapturedGeometryRead<'_,G>,turn:&mut PreparationTurn<'_,'_>)->Result<(),&'static str>{
  let frame_bytes=std::mem::size_of::<Frame>();
  if self.phase==PreparationPhase::Admitting{
   if read.source_bytes>self.request.limits.source_bytes{return Err("preparation-source-byte-limit")}
   if self.allocation==0{let count=read.graph.len().checked_mul(2).ok_or("preparation-source-count-overflow")?.max(2);self.slots=count.checked_next_power_of_two().ok_or("preparation-source-count-overflow")?;self.page_count=self.slots.div_ceil(PAGE_SLOTS);let frame_pages=self.request.limits.depth.checked_add(1).ok_or("preparation-depth-overflow")?.div_ceil(FRAME_PAGE_SLOTS);let index_bytes=self.page_count.checked_mul(std::mem::size_of::<Box<IndexPage>>()).ok_or("preparation-scratch-byte-limit")?;let total=self.page_count.checked_mul(std::mem::size_of::<IndexPage>()).and_then(|v|v.checked_add(index_bytes)).and_then(|v|v.checked_add(frame_pages.checked_mul(std::mem::size_of::<FramePage>()+std::mem::size_of::<Box<FramePage>>())?)).ok_or("preparation-scratch-byte-limit")?;if total>self.request.limits.scratch_bytes{return Err("preparation-scratch-byte-limit")}if !self.admit(turn,std::mem::size_of::<Vec<Box<IndexPage>>>(),index_bytes,0,1)?{return Ok(())}let mut pages=Vec::new();pages.try_reserve_exact(self.page_count).map_err(|_|"preparation-index-allocation-failed")?;self.scratch_bytes+=pages.capacity()*std::mem::size_of::<Box<IndexPage>>();self.pages=Some(pages);self.source_bytes=read.source_bytes;self.source_identity=Some(read.graph.source_identity());self.source_length=Some(read.graph.len());self.allocation=1;return Ok(())}
   if self.pages.as_ref().unwrap().len()<self.page_count{let bytes=std::mem::size_of::<IndexPage>();if !self.admit(turn,bytes*2,bytes,0,1)?{return Ok(())}self.pages.as_mut().unwrap().push(Box::new([Slot::default();PAGE_SLOTS]));self.scratch_bytes+=bytes;return Ok(())}
   let frame_pages=(self.request.limits.depth+1).div_ceil(FRAME_PAGE_SLOTS);if self.frames.is_none(){let bytes=frame_pages*std::mem::size_of::<Box<FramePage>>();if !self.admit(turn,std::mem::size_of::<Vec<Box<FramePage>>>(),bytes,0,1)?{return Ok(())}let mut frames=Vec::new();frames.try_reserve_exact(frame_pages).map_err(|_|"preparation-frame-allocation-failed")?;self.scratch_bytes+=frames.capacity()*std::mem::size_of::<Box<FramePage>>();self.frames=Some(frames);return Ok(())}
   if self.frames.as_ref().unwrap().len()<frame_pages{let bytes=std::mem::size_of::<FramePage>();if !self.admit(turn,bytes*2,bytes,0,1)?{return Ok(())}self.frames.as_mut().unwrap().push(Box::new([Frame::new(0,0);FRAME_PAGE_SLOTS]));self.scratch_bytes+=bytes;return Ok(())}
   if self.admit(turn,128,0,0,1)?{self.phase=PreparationPhase::Indexing}return Ok(())
  }
  if self.phase==PreparationPhase::Indexing{if !self.admit(turn,frame_bytes,0,0,1)?{return Ok(())}if self.source==read.graph.len(){self.phase=if matches!(self.request.scope,PreparationScope::Model){PreparationPhase::Relationships}else{PreparationPhase::Projecting};if matches!(self.request.scope,PreparationScope::Product(_)){self.push(Frame::new(1,self.target))?;}self.probe=None;return Ok(())}let entity=read.graph.entity(self.source).ok_or("preparation-missing-source-entity")?;if entity.id==0{return Err("preparation-invalid-source-id")}if entity.name=="IFCRELVOIDSELEMENT"&&entity.args.get(4).and_then(GeometryValue::as_reference)==Some(self.target){return Err("preparation-opening-frontier-not-implemented")}let probe=*self.probe.get_or_insert((hash(entity.id)as usize)&(self.slots-1));let existing=self.entry(probe);if existing.id==entity.id{return Err("preparation-duplicate-source-id")}if existing.id==0{self.store(probe,entity.id,self.source);self.source+=1;self.probe=None}else{self.probe=Some((probe+1)%self.slots)}return Ok(())}
  if matches!(self.phase,PreparationPhase::Relationships|PreparationPhase::Selecting|PreparationPhase::Retiring|PreparationPhase::Publishing){return self.model_step(read,turn)}
  if self.depth!=0{if self.tessellation_transfer(turn)?{return Ok(())}if !self.admit(turn,frame_bytes*3,0,0,self.depth.min(self.request.limits.depth))?{return Ok(())}let mut top=self.read_frame(self.depth-1);if top.ordinal==0&&top.id!=0{let probe=*self.probe.get_or_insert((hash(top.id)as usize)&(self.slots-1));let existing=self.entry(probe);if existing.id==0{return Err("preparation-missing-reference")}if existing.id==top.id{if matches!(self.request.scope,PreparationScope::Model)&&top.kind==1&&existing.ordinal&(1<<63)!=0{return Err("preparation-opening-frontier-not-implemented")}top.ordinal=existing.ordinal&!(1<<63);self.write_frame(self.depth-1,top);self.probe=None}else{self.probe=Some((probe+1)%self.slots)}return Ok(())}return self.run(read,top)}
  if self.work>=self.request.limits.work{return Err("preparation-work-limit")}
  if self.points.is_none(){if self.request.limits.vertices-self.vertex_start<8||self.request.limits.triangles-self.triangle_start<12{return Err("preparation-result-limit")}if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<f64>>(),0,0,1)?{self.points=Some(mesh::RetainedMeshPages::new(self.request.limits.vertices,self.request.limits.result_bytes)?)}return Ok(())}
  if self.emitted>=8&&self.triangles.is_none(){if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<u32>>(),0,0,1)?{self.triangles=Some(mesh::RetainedMeshPages::new(self.request.limits.triangles,self.request.limits.result_bytes)?)}return Ok(())}
  if self.emitted<20{let mut primitive=self.read_frame(self.request.limits.depth);let index=self.emitted;if !self.emission_pending{if !self.admit(turn,frame_bytes*2,0,0,1)?{return Ok(())}let value=if index<8{let local=if self.primitive==1{block_point(primitive.dims,index)}else{add(primitive.base[index%4],if index>=4{primitive.vector}else{[0.;3]})};let point=Mat4(primitive.matrix).transform_point(local);if point.iter().any(|v|!v.is_finite()){return Err("preparation-nonfinite-result")}point}else{let mut triangle=BLOCK_TRIANGLES[index-8];if determinant(&Mat4(primitive.matrix))*if self.primitive==2{primitive.vector[2]}else{1.}<0.{triangle.swap(1,2)}triangle.map(f64::from)};for axis in 0..3{primitive.tail[axis]=value[axis].to_bits()}self.write_frame(self.request.limits.depth,primitive);self.emission_pending=true;return Ok(())}let value=[f64::from_bits(primitive.tail[0]),f64::from_bits(primitive.tail[1]),f64::from_bits(primitive.tail[2])];let result=if index<8{let pages=self.points.as_mut().unwrap();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let result=pages.append_funded(value,turn,48,self.request.limits.result_bytes-self.result_bytes);self.work+=pages.work()-before_work;self.result_bytes+=pages.allocated_bytes()-before_bytes;result}else{let triangle=value.map(|v|v as u32);let pages=self.triangles.as_mut().unwrap();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let result=pages.append_funded(triangle,turn,48,self.request.limits.result_bytes-self.result_bytes);self.work+=pages.work()-before_work;self.result_bytes+=pages.allocated_bytes()-before_bytes;result};if result?{self.emitted+=1;self.emission_pending=false}return Ok(())}

  if self.admit(turn,128,0,0,1)?{self.phase=if matches!(self.request.scope,PreparationScope::Model){PreparationPhase::Publishing}else{PreparationPhase::Ready}}Ok(())
 }

 pub fn prepared<'a,G:GeometryGraph>(&'a self,read:&CapturedGeometryRead<'a,G>,index:usize)->Result<Option<PreparedPrimitive<'a>>,&'static str>{self.check_source(read)?;if index>=self.prepared_count(read)?{return Ok(None)}let(mut ordinal,mut representation,mut vertex_start,mut vertex_count,mut triangle_start,mut triangle_count)=(self.product_ordinal,self.representation,0,self.points.as_ref().unwrap().len(),0,self.triangles.as_ref().unwrap().len());if matches!(self.request.scope,PreparationScope::Model){let rows=self.records.as_ref().unwrap();ordinal=rows.get(index*2,0)?as usize;representation=read.graph.entity(rows.get(index*2,1)?as usize).ok_or("preparation-representation-source-missing")?.id;vertex_start=rows.get(index*2,2)?as usize;vertex_count=rows.get(index*2+1,0)?as usize;triangle_start=rows.get(index*2+1,1)?as usize;triangle_count=rows.get(index*2+1,2)?as usize;}let entity=read.graph.entity(ordinal).ok_or("preparation-product-source-missing")?;let label=entity.args.get(2).and_then(GeometryValue::as_str).unwrap_or(entity.name);Ok(Some(PreparedPrimitive{product:entity.id,representation,label,vertices:self.points.as_ref().unwrap(),triangles:self.triangles.as_ref().unwrap(),vertex_start,vertex_count,triangle_start,triangle_count}))}

 pub fn begin_close(&mut self){if self.phase!=PreparationPhase::Closed{self.phase=PreparationPhase::Closing}}
 pub fn close(&mut self,turn:&mut PreparationTurn<'_,'_>)->Result<PreparationProgress,&'static str>{if !matches!(self.phase,PreparationPhase::Closing|PreparationPhase::Closed){return Err("preparation-close-not-started")}if self.phase==PreparationPhase::Closed{return Ok(self.progress())}if let Some(pages)=&mut self.issues{pages.begin_close();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let complete=pages.close(turn);self.work+=pages.work()-before_work;self.result_bytes-=before_bytes-pages.allocated_bytes();if complete?{self.issues=None}return Ok(self.progress())}if let Some(pages)=&mut self.records{pages.begin_close();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let complete=pages.close(turn);self.work+=pages.work()-before_work;self.result_bytes-=before_bytes-pages.allocated_bytes();if complete?{self.records=None}return Ok(self.progress())}if let Some(pages)=&mut self.triangles{pages.begin_close();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let complete=pages.close(turn);self.work+=pages.work()-before_work;self.result_bytes-=before_bytes-pages.allocated_bytes();if complete?{self.triangles=None}return Ok(self.progress())}if let Some(pages)=&mut self.points{pages.begin_close();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let complete=pages.close(turn);self.work+=pages.work()-before_work;self.result_bytes-=before_bytes-pages.allocated_bytes();if complete?{self.points=None}return Ok(self.progress())}if let Some(index)=&mut self.vertices{index.begin_close();let before_work=index.work();let before_bytes=index.allocated_bytes();let complete=index.close(turn);self.work+=index.work()-before_work;self.scratch_bytes-=before_bytes-index.allocated_bytes();if complete?{self.vertices=None}return Ok(self.progress())}if let Some(frames)=&self.frames{if !frames.is_empty(){let bytes=std::mem::size_of::<FramePage>();if self.admit(turn,128,0,bytes,1)?{drop(self.frames.as_mut().unwrap().pop());self.scratch_bytes-=bytes}return Ok(self.progress())}let bytes=frames.capacity()*std::mem::size_of::<Box<FramePage>>();if self.admit(turn,128,0,bytes,1)?{drop(self.frames.take());self.scratch_bytes-=bytes;self.depth=0}return Ok(self.progress())}if let Some(pages)=&self.pages{if !pages.is_empty(){let bytes=std::mem::size_of::<IndexPage>();if self.admit(turn,128,0,bytes,1)?{drop(self.pages.as_mut().unwrap().pop());self.scratch_bytes-=bytes}return Ok(self.progress())}let bytes=pages.capacity()*std::mem::size_of::<Box<IndexPage>>();if self.admit(turn,128,0,bytes,1)?{drop(self.pages.take());self.scratch_bytes-=bytes}return Ok(self.progress())}if self.admit(turn,128,0,0,1)?{self.phase=PreparationPhase::Closed;self.source_bytes=0;self.source_identity=None;self.source_length=None}Ok(self.progress())}
 pub fn terminal_is_empty(&self)->bool{self.phase==PreparationPhase::Closed&&self.pages.is_none()&&self.frames.is_none()&&self.points.is_none()&&self.triangles.is_none()&&self.records.is_none()&&self.issues.is_none()&&self.vertices.is_none()}
}
